    /// Scenario: Filter a mixed Claude Code, OpenCode, Pi, and Codex session set
    /// with `type:` tokens and ordinary text. Every registry identity must match
    /// case-insensitively, compose with text using AND semantics, and reject an
    /// unknown type while the existing id/cwd/status/display-name searches work.
    /// Multiple type constraints compose with true AND semantics, so conflicting
    /// identities such as `type:codex type:claude` match no session.
    #[spec("dashboard/filter/003")]
    #[test]
    fn filter_003_agent_type_tokens_compose_with_text() {
        let (state, mut ui) = typed_filter_fixture();
        let mut matching_ids = |query: &str| {
            ui.filter_text = query.to_string();
            filter_sessions(&state, &ui)
                .into_iter()
                .map(|(id, _)| id.as_str())
                .collect::<Vec<_>>()
        };

        for (query, expected) in [
            ("type:claude", "claude-session"),
            ("type:ClaudeCode", "claude-session"),
            ("type:opencode", "opencode-session"),
            ("type:pi", "pi-session"),
            ("type:codex", "codex-session"),
            ("TYPE:CODEX", "codex-session"),
        ] {
            assert_eq!(
                matching_ids(query),
                vec![expected],
                "{query:?} must select only its registry agent type"
            );
        }

        for (query, expected) in [
            ("claude-session", "claude-session"),
            ("open-worktree", "opencode-session"),
            ("thinking", "pi-session"),
            ("wrapped-worker", "codex-session"),
        ] {
            assert_eq!(
                matching_ids(query),
                vec![expected],
                "plain query {query:?} must preserve existing filter semantics"
            );
        }

        assert_eq!(
            matching_ids("type:codex wrapped-worker"),
            vec!["codex-session"],
            "type and text terms must both match"
        );
        assert!(
            matching_ids("type:codex planner").is_empty(),
            "a matching type must not bypass a non-matching text term"
        );
        assert!(
            matching_ids("type:bogus").is_empty(),
            "an unknown agent type must match no sessions"
        );
        assert!(
            matching_ids("type:codex type:claude").is_empty(),
            "multiple type constraints use AND semantics, so no session can be both Codex and Claude Code"
        );
    }

    /// Scenario: From the dashboard, press `/` and type `type:codex` through the
    /// normal filter-input handlers, then render the resulting card list. The
    /// visible dashboard must contain the Codex card and hide the Claude Code,
    /// OpenCode, and Pi cards.
    #[spec("dashboard/filter/004")]
    #[test]
    fn filter_004_slash_type_filter_narrows_rendered_cards() {
        let (state, mut ui) = typed_filter_fixture();
        let action = handle_normal_key(
            KeyEvent::new(KeyCode::Char('/'), KeyModifiers::NONE),
            &mut ui,
            state.sessions.len(),
            None,
            &KeybindingConfig::default(),
        );
        assert!(matches!(action, Action::EnterFilter));
        ui.mode = UiMode::Filter;
        for c in "type:codex".chars() {
            handle_filter_key(KeyEvent::new(KeyCode::Char(c), KeyModifiers::NONE), &mut ui);
        }

        let filtered = filter_sessions(&state, &ui);
        let cards: Vec<(&SessionState, Option<&str>)> = filtered
            .iter()
            .map(|(id, session)| (*session, ui.display_names.get(*id).map(String::as_str)))
            .collect();
        let buffer = render_dashboard_cards_to_buffer(
            &cards,
            ui.selected_index,
            CardDensityKind::Normal,
            0,
            100,
        );
        let visible: String = (0..buffer.area().height)
            .map(|y| {
                (0..buffer.area().width)
                    .map(|x| buffer[(x, y)].symbol())
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n");

        assert!(
            visible.contains("wrapped-worker"),
            "typing type:codex must leave the Codex card visible:\n{visible}"
        );
        for hidden in ["planner", "frontend", "test-runner"] {
            assert!(
                !visible.contains(hidden),
                "typing type:codex must hide the {hidden} card:\n{visible}"
            );
        }
    }

    // ---------------------------------------------------------------------------
    // Mode transition tests
    // ---------------------------------------------------------------------------

    #[test]
    fn test_mode_transitions() {
        let mut ui = default_ui();
        assert_eq!(ui.mode, UiMode::Normal);

        // Normal -> Filter: PRD #80 M4 routes `/` through `dispatch_action`
        // (shared by the `[Filter /]` button), so the handler returns
        // `Action::EnterFilter` rather than flipping the mode inline.
        let filter_action = handle_normal_key(
            KeyEvent::new(KeyCode::Char('/'), KeyModifiers::NONE),
            &mut ui,
            3,
            None,
            &KeybindingConfig::default(),
        );
        assert!(matches!(filter_action, Action::EnterFilter));
        ui.mode = UiMode::Filter;
        assert_eq!(ui.mode, UiMode::Filter);

        // Filter -> Normal (Esc)
        handle_filter_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE), &mut ui);
        assert_eq!(ui.mode, UiMode::Normal);

        // Normal -> Help: PRD #80 M2 routes `?` through `dispatch_action`
        // (shared by the `[Help ?]` button), so the handler now returns
        // `Action::ToggleHelp` rather than flipping the mode inline. Apply the
        // transition the way `dispatch_action` would so the test continues from
        // Help mode.
        let help_action = handle_normal_key(
            KeyEvent::new(KeyCode::Char('?'), KeyModifiers::NONE),
            &mut ui,
            3,
            None,
            &KeybindingConfig::default(),
        );
        assert!(matches!(help_action, Action::ToggleHelp));
        ui.mode = UiMode::Help;
        assert_eq!(ui.mode, UiMode::Help);

        // Help -> Normal
        handle_help_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE), &mut ui);
        assert_eq!(ui.mode, UiMode::Normal);

        // Normal -> Rename: PRD #80 M4 routes `r` through `dispatch_action`
        // (shared by the `[Rename r]` button), so the handler returns
        // `Action::EnterRename` rather than flipping the mode inline.
        let rename_action = handle_normal_key(
            KeyEvent::new(KeyCode::Char('r'), KeyModifiers::NONE),
            &mut ui,
            3,
            None,
            &KeybindingConfig::default(),
        );
        assert!(matches!(rename_action, Action::EnterRename));
        ui.mode = UiMode::Rename;
        assert_eq!(ui.mode, UiMode::Rename);

        // Rename -> Normal (Esc)
        handle_rename_key(
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
            &mut ui,
            Some("s1"),
        );
        assert_eq!(ui.mode, UiMode::Normal);
    }

    // M2.11 fixup 5 — handle_rename_key no longer writes to
    // ui.display_names on Enter; the dispatch loop now calls
    // `pane.rename_pane` first and mirrors the controller-returned
    // RenameOutcome into both display-name maps. These tests pin
    // the residual handler responsibilities: clearing rename_text
    // and returning to Normal mode. The full commit pathway (handler
    // → controller → UI maps) is covered by
    // `tests/agent_metadata.rs::rename_outcome_*` and
    // `rename_pane_*_on_local_backend` in this crate.
    #[test]
    fn test_rename_handler_clears_buffer_and_exits_on_enter() {
        let mut ui = default_ui();
        ui.mode = UiMode::Rename;
        ui.rename_text = "my-agent".to_string();

        handle_rename_key(
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            &mut ui,
            Some("session-123"),
        );

        assert_eq!(ui.mode, UiMode::Normal);
        assert!(
            ui.rename_text.is_empty(),
            "rename_text must be cleared after Enter"
        );
        // Crucially: handler does NOT touch display_names. The
        // dispatch loop mirrors the controller's RenameOutcome
        // into the maps so the raw input never reaches them.
        assert!(
            !ui.display_names.contains_key("session-123"),
            "handler must not insert raw rename_text into display_names"
        );
    }

    #[test]
    fn test_rename_handler_preserves_existing_label_on_enter() {
        // Even when the handler runs with non-empty rename_text, it
        // must not mutate display_names — the dispatch loop owns
        // both maps now, gated by the RenameOutcome.
        let mut ui = default_ui();
        ui.display_names
            .insert("s1".to_string(), "old-name".to_string());
        ui.mode = UiMode::Rename;
        ui.rename_text.clear();

        handle_rename_key(
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            &mut ui,
            Some("s1"),
        );

        assert_eq!(ui.mode, UiMode::Normal);
        assert_eq!(
            ui.display_names.get("s1"),
            Some(&"old-name".to_string()),
            "handler must NOT remove existing display_names entry — \
             the dispatch loop owns that based on RenameOutcome::Cleared"
        );
    }

    #[test]
