    /// PRD #220 seed scope: the seed teaches Agent Deck MECHANICS, not work
    /// methodology. The planner framing was cut deliberately (see the Design
    /// record in `prds/220-…md`), and "NEVER do the work yourself" in particular
    /// forbade the pane from doing anything else the user asked. Pinned so it
    /// cannot drift back in.
    #[test]
    fn dispatcher_seed_teaches_mechanics_not_work_methodology() {
        for banned in [
            "decompose",
            "independent units",
            "parallel-ready",
            "2-6",
            "NEVER do the work yourself",
        ] {
            assert!(
                !DISPATCHER_SEED_PROMPT.contains(banned),
                "the dispatcher seed must not carry work-methodology copy, found {banned:?}"
            );
        }
        // The mechanics it MUST still carry.
        for required in [
            "dot-agent-deck dispatch <name>",
            "SELF-CONTAINED",
            "../<repo>-dispatch-<name>",
            "single-use",
            "fire-and-forget",
            // The shape choice is a deck mechanic (which spawn shape to start),
            // not a work-methodology opinion — so it belongs, and the seed must
            // tell the agent to ASK rather than infer it.
            "--list-targets",
            "--single",
            "--orchestration",
            "ASK, do not guess",
            // The unit shares the repo, so referencing beats pasting — and paths
            // must be relative, or an absolute one points the unit back at the
            // caller's checkout and undoes the isolation.
            "REFERENCE them by path",
            "RELATIVE to the repo root",
        ] {
            assert!(
                DISPATCHER_SEED_PROMPT.contains(required),
                "the dispatcher seed must still teach {required:?}"
            );
        }
    }

    /// PRD #220: the flag-ON cycler wiring. `dispatcher_index()` is index
    /// arithmetic over two independently-gated options, which is exactly what
    /// breaks silently — and the only other coverage is the credential-gated e2e
    /// test, so without this the wiring is untested on a machine with no agent
    /// CLI installed.
    #[test]
    fn dispatcher_occupies_the_last_cycler_slot_when_shown() {
        let mut f = NewPaneFormState::new(
            PathBuf::from("/tmp"),
            String::new(),
            String::new(),
            vec![make_mode("a")],
            vec![],
        );
        // Both experimental options on, independent of the ambient env flag.
        f.show_issue_dispatch = true;
        f.show_dispatcher = true;

        // "No mode" + 1 mode + schedule + schedule: issues + dispatcher.
        assert_eq!(f.mode_option_count(), 5);
        let last = f.mode_option_count() - 1;
        assert_eq!(
            f.dispatcher_index(),
            last,
            "dispatcher must be the LAST cycler slot, after schedule: issues"
        );
        assert_eq!(f.mode_option_name(last), DISPATCHER_MODE_NAME);

        f.selection_index = last;
        assert!(f.is_dispatcher_selected());
        assert_eq!(
            f.selected_mode().map(|m| m.name.as_str()),
            Some(DISPATCHER_MODE_NAME)
        );
        // PRD #220: a dispatcher pane has continued purpose, so it must NOT be
        // labelled "↳ authoring (one-off)" the way the schedule options are.
        assert!(
            !f.is_authoring_selected(),
            "dispatcher is a real mode tab, not throwaway authoring"
        );

        // Flag off: the cycler shape is the pre-feature baseline and the
        // dispatcher is unreachable.
        f.show_dispatcher = false;
        f.selection_index = 0;
        assert_eq!(f.mode_option_count(), 4);
        assert!(!f.is_dispatcher_selected());
    }

    /// PRD #220: submitting the dispatcher option must spawn a dashboard CARD,
    /// never a mode tab.
    ///
    /// A mode tab routes through `render_mode_tab`'s 50/50 split, and
    /// `mode_side_pane_dims` halves the width unconditionally — so a mode with no
    /// side panes (which the dispatcher is) renders the agent at half width beside
    /// an empty column. PRD #127 hit this first and fixed it the same way for the
    /// `schedule` option. This pins the spawn shape so it cannot regress: the
    /// synthetic mode is for the cycler's title/chip only, and the seed must ride
    /// on the REQUEST.
    #[test]
    fn dispatcher_submits_as_a_dashboard_card_not_a_mode_tab() {
        let mut f = NewPaneFormState::new(
            PathBuf::from("/tmp/repo"),
            String::new(),
            String::new(),
            vec![],
            vec![],
        );
        f.show_issue_dispatch = true;
        f.show_dispatcher = true;
        f.selection_index = f.dispatcher_index();
        assert!(
            f.is_dispatcher_selected(),
            "test targets the dispatcher slot"
        );

        let req = build_new_pane_request(&f, "claude");
        assert!(
            req.mode_config.is_none(),
            "the dispatcher must NOT spawn a mode tab — that is the 50/50-split bug"
        );
        assert!(req.orchestration_config.is_none());
        let seed = req
            .seed_prompt
            .as_deref()
            .expect("the dispatcher card must carry its seed on the request");
        assert!(
            seed.starts_with(DISPATCHER_SEED_PROMPT),
            "the card's seed must be the dispatcher seed, got:\n{seed}"
        );
        assert!(
            seed.contains("working_dir: /tmp/repo"),
            "the seed must still be dir-qualified, got:\n{seed}"
        );

        // The cycler still names it, via the synthetic mode.
        assert_eq!(
            f.selected_mode().map(|m| m.name.as_str()),
            Some(DISPATCHER_MODE_NAME)
        );
    }

    // --- PRD #127 M3.3: "Scheduled Tasks" manager dialog pure-data helpers ---

    fn make_scheduled_task(name: &str, enabled: bool) -> config::ScheduledTask {
        config::ScheduledTask {
            name: name.to_string(),
            cron: "0 9 * * *".to_string(),
            working_dir: "/tmp".to_string(),
            command: Some("cat".to_string()),
            prompt: format!("{name}-prompt-marker"),
            new_tab_per_fire: false,
            enabled,
            issue_dispatch: None,
        }
    }

    #[test]
    fn manager_status_label_derivation() {
        assert_eq!(schedule_status_label(false, false), "disabled");
        assert_eq!(schedule_status_label(false, true), "disabled"); // disabled wins
        assert_eq!(schedule_status_label(true, true), "live");
        assert_eq!(schedule_status_label(true, false), "idle");
    }

    #[test]
    fn manager_next_fire_display_disabled_is_placeholder() {
        let disabled = make_scheduled_task("paused", false);
        assert_eq!(schedule_next_fire_display(&disabled), "\u{2014}"); // —

        // An enabled task with a valid cron renders a concrete next-fire.
        let enabled = make_scheduled_task("digest", true);
        let next = schedule_next_fire_display(&enabled);
        assert_ne!(next, "\u{2014}");
        assert!(
            next.contains("09:") || next.contains(" 9:"),
            "next-fire should reflect the 09:00 cron, got {next}"
        );
    }

    #[test]
    fn manager_add_authoring_mode_is_blank_base_seed() {
        let mode = build_schedule_authoring_mode(None, std::path::Path::new("/tmp/picked"));
        assert_eq!(mode.name, SCHEDULE_MODE_NAME);
        let seed = mode.seed_prompt.as_deref().unwrap();
        // Add starts from the base seed (invokes `schedule add`, no edit block) —
        // PRD #170 appends the picked-dir working_dir DEFAULT line.
        assert!(
            seed.starts_with(SCHEDULE_AUTHORING_SEED_PROMPT),
            "add seed must begin with the base authoring seed"
        );
        assert!(seed.contains("schedule add"));
        // PRD #170: the picked dir is threaded in as the working_dir DEFAULT.
        assert!(
            seed.contains("working_dir DEFAULT: /tmp/picked"),
            "add seed must carry the picked dir as the working_dir default, got:\n{seed}"
        );
    }

    #[test]
    fn manager_edit_authoring_mode_prefills_and_forbids_rename() {
        // PRD #170 finding 3: the row's stored dir (A) and the re-picked dir (B)
        // are distinct, non-overlapping paths so the assertions below can tell the
        // stale current-value from the picked default.
        let mut existing = make_scheduled_task("digest", true);
        existing.working_dir = "/row/dir/alpha".to_string();
        let mode =
            build_schedule_authoring_mode(Some(&existing), std::path::Path::new("/pick/dir/bravo"));
        assert_eq!(mode.name, SCHEDULE_MODE_NAME);
        let seed = mode.seed_prompt.as_deref().unwrap();
        // PRD #170: the picked dir is threaded in as the working_dir DEFAULT.
        assert!(
            seed.contains("working_dir DEFAULT: /pick/dir/bravo"),
            "edit seed must carry the picked dir as the working_dir default, got:\n{seed}"
        );
        // PRD #170 finding 3: the re-picked dir wins — the row's stale stored
        // working_dir must NOT survive as a conflicting current value.
        assert!(
            !seed.contains("/row/dir/alpha"),
            "the re-picked working_dir must win; the row's stale dir must not appear, got:\n{seed}"
        );
        // Pre-fill: the existing entry's distinctive prompt + name reach the seed.
        assert!(
            seed.contains("digest-prompt-marker"),
            "edit seed must carry the row's current prompt"
        );
        assert!(
            seed.contains("digest"),
            "edit seed must carry the row's name"
        );
        // Edit drives `schedule update`, never `add`-as-rename, and forbids rename.
        assert!(
            seed.contains("schedule update"),
            "edit seed must instruct `schedule update`"
        );
        assert!(
            seed.to_lowercase().contains("rename is forbidden"),
            "edit seed must forbid renaming (name is the reuse key)"
        );
    }

    // PRD #127 N2 — the scroll window keeps the selected row visible.
    #[test]
    fn manager_visible_window_scrolls_selection_into_view() {
        // Fewer rows than the window → show all.
        assert_eq!(visible_window(3, 0, 5), (0, 3));
        assert_eq!(visible_window(3, 2, 5), (0, 3));

        // More rows than the window: selection at the top stays at offset 0.
        assert_eq!(visible_window(10, 0, 4), (0, 4));
        // Selection beyond the first window scrolls so it's the last visible row.
        assert_eq!(visible_window(10, 5, 4), (2, 6));
        // Selection at the very end pins the window to the bottom.
        assert_eq!(visible_window(10, 9, 4), (6, 10));

        // Degenerate inputs.
        assert_eq!(visible_window(0, 0, 4), (0, 0));
        assert_eq!(visible_window(5, 0, 0), (0, 0));
    }

    // Issue #142 — every `UiMode`'s wheel modality is declared explicitly. The
    // bug was an OMISSION: `ScheduledTasks` was missing from the wheel-blocking
    // guard, so wheeling over the manager dialog scrolled the mode-tab side pane
    // behind it. Listing all variants here (paired with the exhaustive `match` in
    // `overlay_blocks_mouse`, which has no `_` arm) makes a repeat of that
    // omission fail loudly rather than silently leak.
    #[test]
    fn overlay_blocks_mouse_is_declared_for_every_ui_mode() {
        // Topmost overlays: the wheel must never reach the pane behind them.
        for mode in [
            UiMode::QuitConfirm,
            UiMode::StopConfirm,
            UiMode::CloseConfirm,
            UiMode::ConfigGenPrompt,
            UiMode::StarPrompt,
            UiMode::Help,
            UiMode::DirPicker,
            UiMode::NewPaneForm,
            UiMode::ScheduledTasks,
        ] {
            assert!(
                overlay_blocks_mouse(&mode),
                "{mode:?} is a topmost overlay — the wheel must not reach the pane behind it"
            );
        }

        // Non-overlay modes keep the ordinary pane scroll / child-app forwarding.
        for mode in [
            UiMode::Normal,
            UiMode::Filter,
            UiMode::Rename,
            UiMode::PaneInput,
        ] {
            assert!(
                !overlay_blocks_mouse(&mode),
                "{mode:?} has no blocking overlay — pane scrolling must stay live"
            );
        }
    }

    // Issue #142 — the wheel and `j`/`k` share one step definition, so the
    // manager's wheel WRAPS at both ends exactly like the keyboard, and an empty
    // list can neither panic nor underflow.
    #[test]
    fn manager_selection_step_wraps_like_the_keyboard() {
        assert_eq!(step_scheduled_selection(0, 3, true), 1);
        assert_eq!(step_scheduled_selection(1, 3, false), 0);
        // Wrap at both ends, matching `(sel + 1) % len` / `(sel + len - 1) % len`.
        assert_eq!(step_scheduled_selection(2, 3, true), 0);
        assert_eq!(step_scheduled_selection(0, 3, false), 2);
        // Single row: every step is a no-op.
        assert_eq!(step_scheduled_selection(0, 1, true), 0);
        assert_eq!(step_scheduled_selection(0, 1, false), 0);
        // Empty list: `selected` comes back UNCHANGED, no underflow on `len - 1`.
        // A nonzero input is the only one that proves "unchanged" — `0 -> 0`
        // would also pass for a helper that clamped everything to zero.
        assert_eq!(step_scheduled_selection(4, 0, true), 4);
        assert_eq!(step_scheduled_selection(4, 0, false), 4);
    }

    // Issue #142 (review finding 3) — pin the KEYBOARD ENTRY POINT, not just the
    // shared helper: `j`/Down step forward, `k`/Up step back, both wrap at both
    // ends, and an empty list leaves the selection alone. The helper test above
    // exercises `step_scheduled_selection` in isolation and the e2e tests drive
    // the WHEEL, so neither would notice a future edit that unwires one of these
    // four keys or flips its direction. This test would.
    #[test]
    fn manager_keyboard_steps_selection_in_both_directions() {
        fn press(ui: &mut UiState, code: KeyCode) -> usize {
            let action = handle_scheduled_tasks_key(KeyEvent::new(code, KeyModifiers::NONE), ui);
            assert!(
                matches!(action, Action::Continue),
                "{code:?} must only move the selection, never emit an action"
            );
            assert_eq!(
                ui.mode,
                UiMode::ScheduledTasks,
                "{code:?} must leave the manager dialog open"
            );
            ui.scheduled_selected
        }

        let mut ui = default_ui();
        ui.mode = UiMode::ScheduledTasks;
        ui.scheduled_tasks = vec![
            make_scheduled_task("a", true),
            make_scheduled_task("b", true),
            make_scheduled_task("c", true),
        ];
        ui.scheduled_selected = 0;

        // Forward: `j` and Down each advance exactly one row...
        assert_eq!(press(&mut ui, KeyCode::Char('j')), 1, "`j` must move DOWN");
        assert_eq!(press(&mut ui, KeyCode::Down), 2, "Down must move DOWN");
        // ...and wrap off the last row back to the first.
        assert_eq!(
            press(&mut ui, KeyCode::Char('j')),
            0,
            "`j` on the last row must wrap to the first"
        );
        assert_eq!(press(&mut ui, KeyCode::Down), 1, "Down must move DOWN");
        assert_eq!(press(&mut ui, KeyCode::Down), 2, "Down must move DOWN");
        assert_eq!(
            press(&mut ui, KeyCode::Down),
            0,
            "Down on the last row must wrap to the first"
        );

        // Backward: `k` and Up each retreat one row, wrapping off the first row
        // back to the last.
        assert_eq!(
            press(&mut ui, KeyCode::Char('k')),
            2,
            "`k` on the first row must wrap to the last"
        );
        assert_eq!(press(&mut ui, KeyCode::Char('k')), 1, "`k` must move UP");
        assert_eq!(press(&mut ui, KeyCode::Up), 0, "Up must move UP");
        assert_eq!(
            press(&mut ui, KeyCode::Up),
            2,
            "Up on the first row must wrap to the last"
        );

        // Empty list: a NONZERO selection survives every one of the four keys
        // untouched — no clamp to zero, no underflow on `len - 1`, no panic.
        ui.scheduled_tasks.clear();
        ui.scheduled_selected = 4;
        for code in [
            KeyCode::Char('j'),
            KeyCode::Char('k'),
            KeyCode::Down,
            KeyCode::Up,
        ] {
            assert_eq!(
                press(&mut ui, code),
                4,
                "{code:?} must leave an empty list's selection unchanged"
            );
        }
    }

    // PRD #127 N2 — the manager dialog stays OPEN after run-now and after a
    // confirmed delete, so the user can act on multiple rows (the action is
    // dispatched by the main loop, which refreshes the list in place).
    #[test]
    fn manager_run_now_and_delete_keep_dialog_open() {
        let mut ui = default_ui();
        ui.mode = UiMode::ScheduledTasks;
        ui.scheduled_tasks = vec![make_scheduled_task("a", true)];
        ui.scheduled_selected = 0;

        // run-now → emits ScheduleRunNow and leaves the dialog open.
        let r = handle_scheduled_tasks_key(
            KeyEvent::new(KeyCode::Char('r'), KeyModifiers::NONE),
            &mut ui,
        );
        assert!(matches!(r, Action::ScheduleRunNow(ref n) if n == "a"));
        assert_eq!(ui.mode, UiMode::ScheduledTasks);

        // d → confirmation (dialog stays open), then y → ScheduleDelete, still open.
        let r = handle_scheduled_tasks_key(
            KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE),
            &mut ui,
        );
        assert!(matches!(r, Action::Continue));
        assert!(ui.scheduled_delete_confirm);
        assert_eq!(ui.mode, UiMode::ScheduledTasks);

        let r = handle_scheduled_tasks_key(
            KeyEvent::new(KeyCode::Char('y'), KeyModifiers::NONE),
            &mut ui,
        );
        assert!(matches!(r, Action::ScheduleDelete(ref n) if n == "a"));
        assert_eq!(ui.mode, UiMode::ScheduledTasks);
        assert!(!ui.scheduled_delete_confirm);
    }

    // PRD #127 M3.2: the new-deck dialog's Mode cycler always ends with a
    // built-in "schedule" authoring option (after the project modes and
    // orchestrations). PRD #170 finding 7: the seed no longer rides on the
    // synthetic mode (that field is dead data, left `None`) — it is derived at
    // submit time by `build_schedule_authoring_mode`, so the SPAWN REQUEST is what
    // carries it. This test pins both: the option is last/selectable, and
    // submitting it produces a seeded request.
    #[test]
    fn unified_form_builtin_schedule_option_is_offered_and_seeded() {
        let mut f = NewPaneFormState::new(
            PathBuf::from("/tmp"),
            String::new(),
            String::new(),
            vec![make_mode("build")],
            vec![make_orchestration("review")],
        );
        // 0=No mode, 1=build, 2=review, 3=schedule, 4=dispatcher.
        assert_eq!(f.schedule_index(), 3);
        assert_eq!(f.mode_option_count(), 5);

        // PRD #220: `schedule` is no longer the LAST slot — the graduated
        // `dispatcher` option now sits after it, so cycling to the cap lands
        // there. This test is about the schedule option's own identity and seed,
        // so select it directly rather than by saturating the cycler.
        for _ in 0..10 {
            f.select_next_mode();
        }
        assert!(
            f.is_dispatcher_selected(),
            "the cycler cap must now land on `dispatcher`, the last slot"
        );
        f.selection_index = f.schedule_index();
        assert!(f.is_schedule_selected());

        // It is a real (synthetic) mode named `schedule`, NOT misread as an
        // orchestration. Finding 7: the synthetic mode no longer carries the seed.
        let seeded = f.selected_mode().expect("schedule yields a mode");
        assert_eq!(seeded.name, "schedule");
        assert!(
            seeded.seed_prompt.is_none(),
            "finding 7: the synthetic mode's seed_prompt is dead data — left None"
        );
        assert!(f.selected_orchestration().is_none());

        // The seed is delivered through the spawn request derived at submit time.
        let req = build_new_pane_request(&f, "claude");
        let seed = req
            .seed_prompt
            .as_deref()
            .expect("submitting the schedule option carries the authoring seed");
        assert!(seed.contains("schedule add"), "seed must invoke the CLI");
        assert!(
            seed.to_lowercase().contains("confirm"),
            "seed must require confirm-before-write"
        );
    }

    // PRD #170 M2.1 (was PRD #127 Part 4) — a blank Command on the "schedule"
    // authoring option must default to the configured `default_command` (not the
    // formerly-hardcoded `claude`, and never a bare $SHELL), for BOTH submit
    // doors: the [Submit] button path (which calls `build_new_pane_request`
    // directly) and the Enter-on-final-field key path.
    #[test]
    fn schedule_blank_command_defaults_to_configured_default_command_both_doors() {
        const DEFAULT_CMD: &str = "configured-agent";

        // Door 1: the [Submit] button path calls build_new_pane_request directly.
        let mut f = NewPaneFormState::new(
            PathBuf::from("/tmp"),
            String::new(),
            String::new(), // blank command
            vec![],
            vec![],
        );
        f.select_next_mode(); // index 0 -> 1 = the built-in "schedule" option
        assert!(f.is_schedule_selected());
        let req = build_new_pane_request(&f, DEFAULT_CMD);
        assert_eq!(
            req.command, DEFAULT_CMD,
            "[Submit] door must default a blank schedule command to default_command, not $SHELL"
        );
        assert!(
            req.seed_prompt.is_some(),
            "authoring seed prompt is carried"
        );

        // Door 2: the Enter-on-final-field key path resolves default_command
        // from `ui.config`.
        let mut ui = default_ui();
        ui.config.default_command = DEFAULT_CMD.to_string();
        ui.mode = UiMode::NewPaneForm;
        ui.new_pane_form = Some(NewPaneFormState::new(
            PathBuf::from("/tmp"),
            String::new(),
            String::new(), // blank command
            vec![],
            vec![],
        ));
        let right = KeyEvent::new(KeyCode::Right, KeyModifiers::NONE);
        handle_new_pane_form_key(right, &mut ui); // select the schedule option
        assert!(ui.new_pane_form.as_ref().unwrap().is_schedule_selected());
        let enter = KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE);
        handle_new_pane_form_key(enter, &mut ui); // Mode -> Name
        handle_new_pane_form_key(enter, &mut ui); // Name -> Command
        let result = handle_new_pane_form_key(enter, &mut ui); // submit
        match result {
            Action::SpawnPane(req) => assert_eq!(
                req.command, DEFAULT_CMD,
                "Enter door must default a blank schedule command to default_command, not $SHELL"
            ),
            other => panic!("expected SpawnPane, got {other:?}"),
        }
    }

